APP_JS = '// radiko-epg SPA prototype: renders the guide client-side from per-area/day JSON.\n// Data sources: window.EPG_EMBED (single-file demo) or fetch(\'data/<area>/<date>.json\').\nvar META = window.EPG_META;\nvar state = { area: \'JP13\', date: META.days[0], data: null };\n// 「今日」は生成日ではなく端末の時計（放送日）で決める。生成が止まって\n// データが古くても、今日が7日分の中にあればその日を今日として開く。\nif (META.days.indexOf(broadcastToday()) >= 0) state.date = broadcastToday();\ntry {\n  state.area = localStorage.getItem(\'radiko-epg-area\') || \'JP13\';\n} catch (e) {}\n// URL is always the bare root (にどねるzzZ\'s decision 2026-11-13): no query params\n// are read or written; area/date live only in app state + localStorage.\n\nfunction esc(s) {\n  return (s || \'\').replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\')\n                  .replace(/>/g, \'&gt;\').replace(/"/g, \'&quot;\');\n}\nfunction p2(n) { return (n < 10 ? \'0\' : \'\') + n; }\nfunction fmt(d) {\n  return \'\' + d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate()) +\n         p2(d.getHours()) + p2(d.getMinutes()) + p2(d.getSeconds());\n}\nfunction broadcastToday() {\n  var n = new Date();\n  if (n.getHours() < 5) n.setDate(n.getDate() - 1);\n  return \'\' + n.getFullYear() + p2(n.getMonth() + 1) + p2(n.getDate());\n}\nfunction hm(ts) { return parseInt(ts.substr(8, 2), 10) + \':\' + ts.substr(10, 2); }\nfunction endLabel(ft, to) {\n  var e = hm(to);\n  if (to.substr(0, 8) !== ft.substr(0, 8) && parseInt(to.substr(8, 2), 10) < 12) {\n    e = (parseInt(to.substr(8, 2), 10) + 24) + \':\' + to.substr(10, 2);\n  }\n  return e;\n}\nfunction bkey(ft, date) {\n  var h = parseInt(ft.substr(8, 2), 10);\n  if (ft.substr(0, 8) === date) return h >= 5 ? h : h + 24;\n  return h + 24;\n}\nfunction dateLabel(ds, withYear) {\n  var y = parseInt(ds.substr(0, 4), 10), m = parseInt(ds.substr(4, 2), 10),\n      d = parseInt(ds.substr(6, 2), 10);\n  var wd = META.weekdays[new Date(y, m - 1, d).getDay() === 0 ? 6 : new Date(y, m - 1, d).getDay() - 1];\n  return (withYear ? y + \'/\' : \'\') + m + \'/\' + d + \'(\' + wd + \')\';\n}\n\nfunction buildHeader() {\n  var sel = document.getElementById(\'area\');\n  var html = \'\';\n  META.regions.forEach(function(rg) {\n    html += \'<optgroup label="\' + esc(rg[0]) + \'">\';\n    rg[1].forEach(function(c) {\n      html += \'<option value="\' + c + \'"\' + (c === state.area ? \' selected\' : \'\') +\n              \'>\' + esc(META.areaName[c]) + \'</option>\';\n    });\n    html += \'</optgroup>\';\n  });\n  sel.innerHTML = html;\n  var tabs = \'\';\n  var tk = broadcastToday();\n  META.days.forEach(function(ds) {\n    tabs += \'<a class="tab\' + (ds === state.date ? \' on\' : \'\') + \'" href="#" data-date="\' +\n            ds + \'">\' + (ds === tk ? \'今日 \' : \'\') + dateLabel(ds) + \'</a>\';\n  });\n  document.getElementById(\'tabs\').innerHTML = tabs;\n}\n\nfunction render(data) {\n  state.data = data;\n  document.getElementById(\'h1note\').textContent =\n    META.areaName[state.area] + \' \' + dateLabel(state.date) + \' の番組表\';\n  document.getElementById(\'gen\').textContent = \'最終更新 \' + META.generated;\n  document.title = META.areaName[state.area] + \'の番組表 \' + dateLabel(state.date) + \' | radiko-epg\';\n  var head = \'<tr><th class="hr">時</th>\';\n  data.stations.forEach(function(st) {\n    head += \'<th><a href="https://radiko.jp/#!/live/\' + st[0] +\n            \'" target="_blank" rel="noopener">\' + esc(st[1]) + \'</a></th>\';\n  });\n  head += \'</tr>\';\n  document.querySelector(\'thead\').innerHTML = head;\n  // bucket programs per station per hour\n  var buckets = data.stations.map(function(st) {\n    var byHour = {};\n    (data.progs[st[0]] || []).forEach(function(pr) {\n      var k = bkey(pr.f, state.date);\n      (byHour[k] = byHour[k] || []).push(pr);\n    });\n    return byHour;\n  });\n  var rows = \'\';\n  for (var hour = 5; hour < 29; hour++) {\n    rows += \'<tr><th class="hr">\' + (hour < 24 ? hour : hour - 24) + \'</th>\';\n    data.stations.forEach(function(st, si) {\n      rows += \'<td>\';\n      (buckets[si][hour] || []).forEach(function(pr) {\n        var body = pr.d || \'\';\n        if (pr.p) body += (body ? \'<br>\' : \'\') + \'出演者：\' + esc(pr.p);\n        rows += \'<div class="pr" data-ft="\' + pr.f + \'" data-to="\' + pr.t + \'">\' +\n                \'<span class="tm">\' + hm(pr.f) + \'–\' + endLabel(pr.f, pr.t) + \'</span> \' +\n                \'<span class="ti\' + (body ? \' has\' : \'\') + \'">\' + esc(pr.ti) + \'</span>\' +\n                (body ? \'<div class="dt" hidden>\' + body + \'</div>\' : \'\') + \'</div>\';\n      });\n      rows += \'</td>\';\n    });\n    rows += \'</tr>\';\n  }\n  document.querySelector(\'tbody\').innerHTML = rows;\n  buildHeader();\n  var cur = markNow();\n  if (cur && state.date === broadcastToday()) {\n    var wrap = document.querySelector(\'.wrap\');\n    var er = cur.getBoundingClientRect(), wr = wrap.getBoundingClientRect();\n    wrap.scrollTop += (er.top - wr.top) - (wrap.clientHeight - er.height) / 2;\n  }\n}\n\nfunction markNow() {\n  var now = fmt(new Date()), cur = null;\n  document.querySelectorAll(\'.pr\').forEach(function(el) {\n    var on = el.dataset.ft <= now && now < el.dataset.to;\n    el.classList.toggle(\'now\', on);\n    if (on) cur = el;\n  });\n  return cur;\n}\n\nfunction load(area, date) {\n  state.area = area; state.date = date;\n  if (window.EPG_EMBED) {\n    var d = window.EPG_EMBED[area + \'/\' + date];\n    if (d) { render(d); }\n    else {\n      document.querySelector(\'tbody\').innerHTML =\n        \'<tr><td style="min-width:300px">この試作デモには東京（JP13）のデータだけが入っています。</td></tr>\';\n      buildHeader();\n    }\n    return;\n  }\n  fetch(\'data/\' + area + \'/\' + date + \'.json\')\n    .then(function(r) { return r.json(); })\n    .then(render)\n    .catch(function() {\n      document.querySelector(\'tbody\').innerHTML =\n        \'<tr><td style="min-width:300px">データを読み込めませんでした。</td></tr>\';\n    });\n}\n\ndocument.getElementById(\'area\').addEventListener(\'change\', function() {\n  try { localStorage.setItem(\'radiko-epg-area\', this.value); } catch (e) {}\n  load(this.value, state.date);\n});\ndocument.getElementById(\'tabs\').addEventListener(\'click\', function(ev) {\n  var a = ev.target.closest(\'a[data-date]\');\n  if (!a) return;\n  ev.preventDefault();\n  load(state.area, a.dataset.date);\n});\ndocument.querySelector(\'tbody\').addEventListener(\'click\', function(ev) {\n  var ti = ev.target.closest(\'.ti.has\');\n  if (!ti) return;\n  var dt = ti.parentElement.querySelector(\'.dt\');\n  if (dt) dt.hidden = !dt.hidden;\n});\nvar fd = document.querySelector(\'footer details\');\nif (fd && window.matchMedia(\'(min-width: 641px)\').matches) fd.open = true;\nvar lastToday = broadcastToday();\nsetInterval(function() {\n  var t = broadcastToday();\n  if (t !== lastToday) {\n    // 開いたまま5時を跨いだら、今日を見ていた場合だけ翌日へ切り替える\n    var wasToday = state.date === lastToday;\n    lastToday = t;\n    if (wasToday && META.days.indexOf(t) >= 0) { load(state.area, t); return; }\n    buildHeader();\n  }\n  markNow();\n}, 60000);\nload(state.area, state.date);\n'

def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "radiko-epg/1.0"})
    with urllib.request.urlopen(req, timeout=30) as r:
        data = r.read()
    if data[:2] == b"\x1f\x8b":  # some radiko endpoints answer gzip unasked
        import gzip
        data = gzip.decompress(data)
    return data


def area_stations(area):
    """[(station_id, name), ...] for one area, in radiko's own order."""
    root = ET.fromstring(fetch(f"http://radiko.jp/v2/station/list/{area}.xml"))
    out = []
    for st in root.iter("station"):
        sid = st.findtext("id")
        name = st.findtext("name")
        if sid:
            out.append((sid.strip(), (name or sid).strip()))
    return out


def station_day(sid, date_str):
    """Programs of one station on one broadcast date; [] on any failure."""
    try:
        root = ET.fromstring(fetch(
            f"https://radiko.jp/v3/program/station/date/{date_str}/{sid}.xml"))
    except Exception as e:  # a missing day must not kill the whole build
        print(f"WARN: {sid} {date_str}: {e}", file=sys.stderr)
        return []
    progs = []

    def txt(p, tag):
        el = p.find(tag)
        return (el.text or "").strip() if el is not None and el.text else ""

    for p in root.iter("prog"):
        progs.append({"ft": p.get("ft"), "to": p.get("to"),
                      "title": txt(p, "title"), "desc": txt(p, "desc"),
                      "pfm": txt(p, "pfm")})
    return progs


def clean_desc(s):
    """Feed descriptions carry raw HTML (<br>, <a ...>) as text.
    Keep <br> as line breaks, strip every other tag (its text stays),
    escape the rest. Links are intentionally left untappable."""
    s = re.sub(r"(?i)<br\s*/?>", "\n", s)
    s = re.sub(r"<[^>]+>", "", s)
    s = html.unescape(s)
    lines = [ln.strip() for ln in s.split("\n")]
    return "<br>".join(html.escape(ln) for ln in lines if ln)


def broadcast_today(now_jst):
    d = now_jst.date()
    if now_jst.hour < 5:
        d -= timedelta(days=1)
    return d



def area_day_json(area, date_str, stations, data):
    progs = {}
    for sid, _name in stations:
        items = []
        for pr in data.get((sid, date_str), []):
            items.append({
                "f": pr["ft"], "t": pr["to"], "ti": pr["title"],
                "d": clean_desc(pr["desc"]) if pr["desc"] else "",
                "p": pr["pfm"],
            })
        if items:
            progs[sid] = items
    return {"area": area, "date": date_str,
            "stations": [[s, n] for s, n in stations], "progs": progs}


